sql.if:
AND (P.OPEN_SCOPE = '전체 공개'
     OR P.WRITER_ID = #{viewerId}
     OR P.WRITER_DEPT = #{viewerDept})

mapper.sql:
WHERE P.BOARD_TYPE = #{boardType}
  AND P.DELETED_YN = 'N'


    AND (P.TITLE LIKE '%' || #{q} || '%' OR P.WRITER LIKE '%' || #{q} || '%')

mapper.select:
SELECT * FROM (
    SELECT A.*, ROWNUM AS RN FROM (
        SELECT P.POST_ID, P.BOARD_TYPE, P.TITLE, P.CATEGORY, P.OPEN_SCOPE, P.PINNED_YN, P.VIEW_COUNT,
               P.WRITER, P.WRITER_DEPT, P.CREATED_AT, P.WRITER_ID, P.UPDATED_AT,
               (SELECT COUNT(*) FROM BOARD_COMMENT C WHERE C.POST_ID = P.POST_ID AND C.DELETED_YN = 'N') AS COMMENT_COUNT
          FROM BOARD_POST P

         ORDER BY CASE WHEN P.PINNED_YN = 'Y' THEN 0 ELSE 1 END, P.CREATED_AT DESC, P.POST_ID DESC
    ) A WHERE ROWNUM <= #{endRow}
) WHERE RN > #{startRow}

mapper.update:
UPDATE BOARD_POST
   SET DELETED_YN = 'Y', DELETED_AT = #{now}, DELETED_BY = #{deletedBy}
 WHERE POST_ID = #{postId}
   AND DELETED_YN = 'N'

mapper.select:
